def _check(self) -> None:
    """
    Based on the newly updated info, check if we should take action or not
    """
    if not self._is_initiated:
        self._is_initiated = True

    self._wait_until_executing_orders_are_fully_handled()

    if jh.is_live() and jh.is_debuggable('strategy_execution'):
        logger.info(f'Executing  {self.name}-{self.exchange}-{self.symbol}-{self.timeframe}')

    # should cancel entry?
    if (len(self.entry_orders) and self.is_close and not self._has_entries_awaiting_fill()
            and self.should_cancel_entry()):
        self._execute_cancel()

        # make sure order cancellation response is received via WS
        if jh.is_live():
            # sleep a little until cancel is received via WS
            sleep(0.1)
            # just in case, sleep some more if necessary
            for _ in range(20):
                if store.orders.count_active_orders(self.exchange, self.symbol) == 0:
                    break

                logger.info('sleeping 0.2 more seconds until cancellation is over...')
                sleep(0.2)

            # If it's still not cancelled, something is wrong. Handle cancellation failure
            if store.orders.count_active_orders(self.exchange, self.symbol) != 0:
                raise exceptions.ExchangeNotResponding(
                    'The exchange did not respond as expected for order cancellation'
                )

    # update position
    if self.position.is_open:
        self._update_position()

        # sleep for 1 second if a MARKET order has been submitted but not executed yet (live trading only)
        if jh.is_livetrading():
            waiting_counter = 0
            waiting_seconds = 1
            while self._have_any_pending_market_exit_orders():
                if jh.is_debugging():
                    logger.info(f'Waiting {waiting_seconds} second for pending market exit orders to be handled...')
                waiting_counter += 1
                if waiting_counter > 22:
                    raise exceptions.ExchangeNotResponding(
                        'The exchange did not respond as expected for order execution'
                    )
                else:
                    sleep(1)

    self._simulate_market_order_execution()

    # should_long and should_short
    if self.position.is_close and self.entry_orders == []:
        self._reset()

        should_short = self.should_short()
        # validate that should_short is not True if the exchange_type is spot
        if self.exchange_type == 'spot' and should_short:
            raise exceptions.InvalidStrategy(
                'should_short cannot be True if the exchange type is "spot".'
            )

        should_long = self.should_long()

        # should_short and should_long cannot be True at the same time
        if should_short and should_long:
            raise exceptions.ConflictingRules(
                'should_short and should_long should not be true at the same time.'
            )

        if should_long:
            self._execute_long()
        elif should_short:
            self._execute_short()

def _have_any_pending_market_exit_orders(self) -> bool:
    return any(o.is_active and o.type == order_types.MARKET for o in self.exit_orders)

@staticmethod
def _simulate_market_order_execution() -> None:
    """
    Simulate market order execution in backtest mode
    """

warmup_num = jh.get_config('env.data.warmup_candles_num', 210)
max_timeframe = jh.max_timeframe(config['app']['considering_timeframes'])

# load and add required warm-up candles for backtest, and then Prepare trading candles
trading_candles = {}
warmup_candles = {}
for c in config['app']['considering_candles']:
    exchange, symbol = c[0], c[1]
    if jh.app_mode() == 'backtest' and not jh.should_execute_silently():
        publish_status(f'Loading historical candles for {symbol} on {exchange}…')
    warmup_candles_arr, trading_candle_arr = candle_service.get_candles_from_db(
        exchange, symbol, max_timeframe, start_date, finish_date, warmup_num, caching=True, is_for_jesse=True
    )

    # Ensure that trading_candle_arr is not None or empty
    if trading_candle_arr is None or (isinstance(trading_candle_arr, np.ndarray) and trading_candle_arr.size == 0):
        _handle_missing_candles(
            exchange, 
            symbol, 
            start_date, 
            f"Missing trading candles for {symbol} on {exchange}"
        )

    try:
        candle_service.validate_observed_one_minute_candles(trading_candle_arr, exchange, symbol)
    except ValueError as exc:
        _handle_missing_candles(exchange, symbol, start_date, str(exc))
    if not _supports_observed_timestamp_replay_scope() and (
        trading_candle_arr[0, 0] > start_date
        or trading_candle_arr[-1, 0] < finish_date - 60_000
    ):
        _handle_missing_candles(exchange, symbol, start_date)

    # add trading candles
    trading_candles[jh.key(exchange, symbol)] = {
        'exchange': exchange,
        'symbol': symbol,
        'candles': trading_candle_arr
    }

    warmup_candles[jh.key(exchange, symbol)] = {
        'exchange': exchange,
        'symbol': symbol,
        'candles': warmup_candles_arr
    }

return warmup_candles, trading_candles

candles_info = [info + (prefilled[idx],) for idx, info in enumerate(candles_info)]

for i in range(length):
    # update time
    if store.funding.enabled:
        store.funding.settle(int(first_candles_set[i, 0]), store)
    store_app.time = first_candles_set[i, 0] + 60_000
    i_next = i + 1

    updated_timeframes = {timeframes.MINUTE_1}

    # add candles
    for candles_arr, candles_pipeline, exchange, symbol, arr_1m in candles_info:
        if arr_1m is not None:
            # The candle is already copied into the storage buffer, so
            # exposing this observed candle only requires an index advance.
            short_candle = candles_arr[i]
            arr_1m.index += 1
        else:
            if candles_pipeline is None:
                short_candle = candles_arr[i]
            else:
                short_candle = candles_pipeline.get_candles(
                    candles_arr[i: i + candles_pipeline._batch_size], i, -1
                )

            # Pipeline output becomes the canonical row used by storage and
            # higher-timeframe generation for this simulation.
            candles_arr[i] = short_candle

            add_candle(short_candle, exchange, symbol, '1m', with_execution=False,
                       with_generation=False)

        # print short candle
        if print_shorter_period_candles:
            candle_service.print_candle(short_candle, True, symbol)

        previous_close = candles_arr[i - 1, 2] if i != 0 else None
        _simulate_price_change_effect(
            short_candle,
            exchange,
            symbol,
            previous_close=previous_close,
        )

        # Timestamp replay publishes every completed clock bucket at the
        # first real source-candle event on or after that bucket's boundary.
        if store.candles.uses_timestamp_buckets:
            for timeframe, start in timestamp_generation_schedule.get(i, []):
                timeframe_ms = TIMEFRAME_TO_ONE_MINUTES[timeframe] * 60_000
                bucket_start = int(candles_arr[start, 0])

if not run_silently:
    last_update_time = _update_progress_bar(progressbar, run_silently, i, candle_step=420,
                                            last_update_time=last_update_time)

# now that all new generated candles are ready, execute
if store.funding.enabled:
    store.funding.settle(int(store_app.time), store)
if store.open_interest.enabled:
    store.open_interest.advance(int(store_app.time))
for r, count, strategy, exchange, symbol in routes_info:
    if store.candles.uses_timestamp_buckets:
        if r.timeframe in updated_timeframes:
            strategy._execute()
    # 1m timeframe
    elif count == 1:
        strategy._execute()
    elif i_next % count == 0:
        # print candle
        if print_trading_candles:
            candle_service.print_candle(candle_service.get_current_candle(exchange, symbol, r.timeframe), False,
                         symbol)
        strategy._execute()

    update_active_orders(exchange, symbol)

# now check to see if there's any MARKET orders waiting to be executed
execute_simulated_market_orders()

# Timestamp-based sampling keeps sparse market closures as real gaps
# instead of treating 1,440 available rows as one calendar day.

def get_storage(self, exchange: str, symbol: str, timeframe: str) -> DynamicNumpyArray:
    # inline jh.key() — this is called multiple times per simulated minute
    try:
        return self.storage[f'{exchange}-{symbol}-{timeframe}']
    except KeyError:
        raise RouteNotFound(symbol, timeframe)

def init_storage(self, bucket_size: int = 1000) -> None:
    for r in router.all_formatted_routes:
        exchange, symbol = r['exchange'], r['symbol']

        # initiate the '1m' timeframes
        key = jh.key(exchange, symbol, timeframes.MINUTE_1)
        self.storage[key] = DynamicNumpyArray((bucket_size, 6))

        for timeframe in config['app']['considering_timeframes']:
            key = jh.key(exchange, symbol, timeframe)
            # ex: 1440 / 60 + 1 (reserve one for forming candle)
            total_bigger_timeframe = int((bucket_size / jh.timeframe_to_one_minutes(timeframe)) + 1)
            self.storage[key] = DynamicNumpyArray((total_bigger_timeframe, 6))

